import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as e,c as t,f as l,q as n,D as p,Q as o,g as i}from"./chunks/runtime-core.esm-bundler.BPXnTuTE.js";const C=JSON.parse('{"title":"SSR 渲染和 RSC 组件的区别","description":"","frontmatter":{},"headers":[],"relativePath":"column/Next/基础/SSR渲染和RSC组件的区别.md","filePath":"column/Next/基础/SSR渲染和RSC组件的区别.md","lastUpdated":1785136738000}'),c={name:"column/Next/基础/SSR渲染和RSC组件的区别.md"};function d(S,s,g,b,u,R){const a=e("ArticleMetadata");return l(),t("div",null,[s[0]||(s[0]=n("h1",{id:"ssr-渲染和-rsc-组件的区别",tabindex:"-1"},[i("SSR 渲染和 RSC 组件的区别 "),n("a",{class:"header-anchor",href:"#ssr-渲染和-rsc-组件的区别","aria-label":'Permalink to "SSR 渲染和 RSC 组件的区别"'},"​")],-1)),p(a),s[1]||(s[1]=o(`<p>在理解了 SSR（服务端渲染）之后，学习 <strong>RSC（React Server Components，React 服务端组件）</strong> 就会非常轻松。</p><p>很多人容易把它们混淆，以为 RSC 是 SSR 的替代品，但事实并非如此：<strong>RSC 不是 SSR 的替代品，而是一种全新的“代码架构模式”。它们完全可以（也经常）结合在一起使用。</strong></p><h2 id="_1-核心定义-什么是-rsc" tabindex="-1">1. 核心定义：什么是 RSC？ <a class="header-anchor" href="#_1-核心定义-什么是-rsc" aria-label="Permalink to &quot;1. 核心定义：什么是 RSC？&quot;">​</a></h2><p>简单来说：<strong>RSC 允许你把 React 组件拆分成两类——“只在服务器运行的组件”和“在浏览器运行的组件”。</strong></p><p>在 RSC 架构下，组件被严苛地分为两类：</p><ul><li><strong>服务端组件（Server Component）</strong>：<strong>只在服务器上运行，代码永远不会下载到浏览器</strong>。它可以直接在组件里读数据库、读取文件系统或请求内部 API。因为它不需要发给浏览器，所以它的依赖库（无论多大）都不占用前端 JS Bundle 的体积。</li><li><strong>客户端组件（Client Component）</strong>：就像我们平时写的普通 React 组件，会在浏览器运行，拥有状态（<code>useState</code>）、生命周期（<code>useEffect</code>）和用户交互事件（<code>onClick</code>）。在 Next.js (App Router) 中，需要在文件顶部显式声明 <code>&#39;use client&#39;</code>。</li></ul><h2 id="_2-rsc-与-ssr-的本质区别" tabindex="-1">2. RSC 与 SSR 的本质区别 <a class="header-anchor" href="#_2-rsc-与-ssr-的本质区别" aria-label="Permalink to &quot;2. RSC 与 SSR 的本质区别&quot;">​</a></h2><p>如果用一句话概括它们的区别：</p><ul><li><strong>SSR 处理的是“页面/请求级别”的渲染流程</strong>（把 HTML 送给浏览器）。</li><li><strong>RSC 处理的是“组件级别”的代码分割与执行位置</strong>（决定哪部分代码留在服务器，哪部分发给客户端）。</li></ul><p>我们从 4 个维度进行对比：</p><table tabindex="0"><thead><tr><th>维度</th><th>SSR（服务端渲染）</th><th>RSC（React 服务端组件）</th></tr></thead><tbody><tr><td><strong>本质属性</strong></td><td>一种<strong>页面加载与渲染策略</strong></td><td>一种<strong>组件架构与代码分割模式</strong></td></tr><tr><td><strong>返回的内容</strong></td><td><strong>HTML 字符串</strong></td><td>专用的 <strong>RSC Payload（一种定制的 JSON 结构）</strong>，用于描述 UI 树</td></tr><tr><td><strong>客户端水合 (Hydration)</strong></td><td><strong>必须水合</strong>（整页下载 JS 并绑定事件）</td><td><strong>服务端组件无需水合</strong>（因为根本没有发 JS 给客户端）</td></tr><tr><td><strong>JS Bundle 体积</strong></td><td>页面用到的所有组件代码<strong>全都要发给客户端</strong></td><td>服务端组件的代码<strong>零字节发送给客户端</strong></td></tr><tr><td><strong>运行节点</strong></td><td>仅在 <strong>首屏页面请求（HTML 阶段）</strong> 时运行一次</td><td><strong>在整个应用生命周期中随时运行</strong>（比如客户端路由切换时重新请求 RSC）</td></tr></tbody></table><h2 id="_3-为什么有了-ssr-还需要-rsc-解答-ssr-的痛点" tabindex="-1">3. 为什么有了 SSR，还需要 RSC？（解答 SSR 的痛点） <a class="header-anchor" href="#_3-为什么有了-ssr-还需要-rsc-解答-ssr-的痛点" aria-label="Permalink to &quot;3. 为什么有了 SSR，还需要 RSC？（解答 SSR 的痛点）&quot;">​</a></h2><p>回顾之前文章讨论的 SSR，传统的 SSR 虽然解决了“首屏白屏”和“SEO”问题，但它有一个致命的隐患：<strong>JS Bundle 体积大，水合开销高。</strong></p><h3 id="传统-ssr-的局限" tabindex="-1">传统 SSR 的局限： <a class="header-anchor" href="#传统-ssr-的局限" aria-label="Permalink to &quot;传统 SSR 的局限：&quot;">​</a></h3><p>在传统 SSR 中，虽然服务器生成了 HTML，但<strong>所有组件的代码（JS）依然要打包发送给浏览器</strong>。</p><blockquote><p><strong>例子：</strong> 你的页面有一个“Markdown 渲染组件”，里面用了庞大的 <code>marked.js</code> 库（比如 100KB）。</p><ul><li>在 <strong>SSR</strong> 下：服务器用 <code>marked</code> 生成了 HTML 文本送给浏览器，但为了客户端后续能够激活（Hydration），<code>marked</code> 这个 100KB 的 JS 库<strong>依然要下载到用户的手机上</strong>。</li><li>在 <strong>RSC</strong> 下：你把这个组件声明为 <strong>Server Component</strong>。服务器直接把 Markdown 转换成 UI 结构，<code>marked</code> 这个库<strong>完全留在服务器</strong>，0 字节发送给客户端！</li></ul></blockquote><h2 id="_4-rsc-与-ssr-是如何协同工作的" tabindex="-1">4. RSC 与 SSR 是如何协同工作的？ <a class="header-anchor" href="#_4-rsc-与-ssr-是如何协同工作的" aria-label="Permalink to &quot;4. RSC 与 SSR 是如何协同工作的？&quot;">​</a></h2><p>在现代主流框架（如 Next.js App Router）中，<strong>RSC 和 SSR 通常是组合使用的</strong>。</p><p>我们看它们在<strong>页面首次加载</strong>和<strong>后续客户端跳转</strong>时的配合流程：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== 场景一：用户首次访问页面 (RSC + SSR 结合) ===</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[1] 用户请求页面 URL</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>[2] Node.js 服务端运行 Server Components (RSC)</span></span>
<span class="line"><span>    (直接在服务器读取数据库/调用 API，不下载第三方大库给客户端)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>[3] 生成 RSC Payload (包含服务端组件的 UI 结构 + 客户端组件的位置)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>[4] 触发 SSR：将 RSC Payload 转化为真实的 HTML 文本</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>[5] 返回 HTML 给浏览器 (用户秒看到界面，FCP)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>[6] 浏览器只下载“客户端组件”的 JS 进行 Hydration (水合)</span></span>
<span class="line"><span>    (水合开销和 JS 体积大幅减少！)</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>=== 场景二：用户在页面内点击链接跳转 (纯 RSC 模式，不再触发 SSR) ===</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[1] 用户点击 \`&lt;Link&gt;\` 跳转到新页面</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>[2] 浏览器向服务器发起 fetch 请求 (请求新页面的 RSC 数据)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>[3] 服务器只运行新页面的 Server Components，返回新页面的 RSC Payload</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>[4] 客户端 React 收到 RSC Payload，无缝将新组件切入当前 DOM 树</span></span>
<span class="line"><span>    (无需重新加载全页 HTML，也不会丢失当前页面未改变的状态！)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">举例：</p><blockquote><p>一个在日常开发中最简单、最常见的例子，就是“网页顶部的顶部导航栏（Header）”<strong>或</strong>“用户信息卡片”。</p></blockquote><p>我们可以看看一个网页最上方的“用户信息头像框”在两种模式下的巨大差异：</p><hr><h3 id="场景-网页顶部的-用户信息卡片" tabindex="-1">场景：网页顶部的“用户信息卡片” <a class="header-anchor" href="#场景-网页顶部的-用户信息卡片" aria-label="Permalink to &quot;场景：网页顶部的“用户信息卡片”&quot;">​</a></h3><p>这个卡片需要做两件事：</p><ol><li><strong>显示信息</strong>：显示用户的名字、头像、积分（纯展示）。</li><li><strong>交互功能</strong>：点击头像弹下拉菜单、点击“退出登录”按钮（交互）。</li></ol><hr><h4 id="_1-在传统-ssr-下-全量打包" tabindex="-1">1. 在传统 SSR 下（全量打包） <a class="header-anchor" href="#_1-在传统-ssr-下-全量打包" aria-label="Permalink to &quot;1. 在传统 SSR 下（全量打包）&quot;">​</a></h4><p>在传统 SSR 中，服务器渲染出这个卡片后，<strong>这个卡片里的所有 JS 代码</strong>都要打包发给客户端。</p><ul><li><strong>问题在于</strong>：为了让那个“下拉菜单”能点击，浏览器不仅下载了下拉菜单的点击逻辑，还被迫下载了<strong>用于格式化名字、格式化积分数字、处理头像默认图等一堆纯展示逻辑的 JS 代码</strong>。</li><li><strong>结果</strong>：客户端要对整个卡片的所有 DOM 节点都做一遍“水合（Hydration）”。</li></ul><hr><h4 id="_2-在-rsc-react-服务端组件-下-精准拆分" tabindex="-1">2. 在 RSC（React 服务端组件）下（精准拆分） <a class="header-anchor" href="#_2-在-rsc-react-服务端组件-下-精准拆分" aria-label="Permalink to &quot;2. 在 RSC（React 服务端组件）下（精准拆分）&quot;">​</a></h4><p>在 RSC 中，你可以把这个简单的卡片拆成两层：</p><ul><li><strong>外层的卡片主体（Server Component）</strong>： 在服务器直接读数据库/API 拿到用户名和头像，渲染成静态结构。<strong>这里的格式化逻辑、数据读取逻辑 0 字节发送给客户端</strong>，客户端也无需水合。</li><li><strong>里层的“下拉菜单按钮”（Client Component <code>&#39;use client&#39;</code>）</strong>： 只有这个控制菜单展开/收起的几十行控制代码会被打包发给客户端。</li></ul><hr><h4 id="对比" tabindex="-1">对比 <a class="header-anchor" href="#对比" aria-label="Permalink to &quot;对比&quot;">​</a></h4><ul><li><strong>传统 SSR</strong>：为了让菜单能点开，把<strong>整个卡片的全部代码</strong>都发给了手机。</li><li><strong>RSC</strong>：只把“打开菜单”这一个动作的代码发给手机，剩下的用户名、头像等纯静态结构完全留在服务器，手机零负担。</li></ul></div><h2 id="_5-总结" tabindex="-1">5. 总结 <a class="header-anchor" href="#_5-总结" aria-label="Permalink to &quot;5. 总结&quot;">​</a></h2><ul><li><strong>SSR</strong> 是“先在服务器把<strong>整页 HTML</strong> 做出来送给浏览器”，解决的是<strong>首屏慢和 SEO</strong> 问题。</li><li><strong>RSC</strong> 是“把<strong>组件</strong>分成服务端和客户端两类”，解决的是 <strong>JS 包太大、水合太慢、组件无法直接读数据库</strong> 的架构问题。</li><li><strong>最佳搭档</strong>：现代 React 开发中，<strong>首屏用 SSR 把它转成 HTML 送出，内部架构用 RSC 把代码留在服务器</strong>，两者结合实现了极致的 Web 性能。</li></ul>`,23))])}const _=r(c,[["render",d]]);export{C as __pageData,_ as default};
